<script>
  import { resizer } from './resizer.js'

  const {
    class: klass = '',
    direction = 'horizontal', // horizontal | vertical
    placement = 'right', // Only works for right and bottom for now.
    target = null,
    minWidth = 0,
    minHeight = 0,
    canExceedOriginal = false,
  } = $props()

  // Notes:
  // - Tricky to get 'left' to work because it requires logical CSS positioning properties which may not be used to create the element.
  // - Tricky to get 'top' to work because it requires element to be bottom-fixed so top can be adjustable.

  const placementClasses = { bottom: 'resizer-bottom', right: 'resizer-right' }
  const directionClasses = {
    horizontal: 'resizer-horizontal',
    vertical: 'resizer-vertical',
  }

  const placementClass = $derived(placementClasses[placement])
  const directionClass = $derived(directionClasses[direction])
  const opts = $derived({
    direction,
    placement,
    target,
    minWidth,
    minHeight,
    canExceedOriginal,
  })
</script>

<div
  class="resizer {placementClass} {directionClass} {klass}"
  use:resizer={opts}
></div>
